class DisSinif:
  class IcSinif:
    def merhaba(self):
      print('İç sınıftan merhaba!')

# DisSinif üzerinden IcSinif'a erişiyoruz
nesne = DisSinif.IcSinif()
nesne.merhaba()

class Ogrenci:
  def __init__(self, isim):
    self.isim = isim
    self.bilgisayar = self.Bilgisayar()

  class Bilgisayar:
    marka = 'HP'

o = Ogrenci('Ayşe')
print(o.isim, 'kullanıcısının bilgisayarı:', o.bilgisayar.marka)

